#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "htslib/sam.h"

/* Minimal samtools substitute supporting:
     view [-S] [-b] [-h] [-T ref.fa] [in]      (in defaults/'-' = stdin)
     merge -f out in1 in2 ...
     index in.bam
*/
static int cmd_view(int argc, char **argv)
{
    int bam_out = 0, with_header = 0;
    const char *ref = NULL;
    const char *in = "-";
    for (int i = 0; i < argc; i++) {
        char *a = argv[i];
        if (a[0] == '-' && a[1] != '\0') {
            for (char *c = a + 1; *c; c++) {
                if (*c == 'b') bam_out = 1;
                else if (*c == 'h') with_header = 1;
                else if (*c == 'S') ;
                else if (*c == 'T') { ref = argv[++i]; break; }
            }
        } else in = a;
    }
    samFile *fp = sam_open(in, "r");
    if (!fp) { fprintf(stderr, "shim: cannot open %s\n", in); return 1; }
    if (ref) hts_set_fai_filename(fp, ref);
    bam_hdr_t *hdr = sam_hdr_read(fp);
    if (!hdr) { fprintf(stderr, "shim: cannot read header\n"); return 1; }
    samFile *out = sam_open("-", bam_out ? "wb" : "w");
    if (bam_out || with_header) {
        if (sam_hdr_write(out, hdr) < 0) return 1;
    }
    bam1_t *b = bam_init1();
    int r;
    while ((r = sam_read1(fp, hdr, b)) >= 0) {
        if (sam_write1(out, hdr, b) < 0) return 1;
    }
    bam_destroy1(b);
    sam_close(out);
    bam_hdr_destroy(hdr);
    sam_close(fp);
    return 0;
}

static int cmd_merge(int argc, char **argv)
{
    const char *outname = NULL;
    int first_in = -1;
    for (int i = 0; i < argc; i++) {
        if (strcmp(argv[i], "-f") == 0) continue;
        if (!outname) { outname = argv[i]; continue; }
        if (first_in < 0) first_in = i;
    }
    if (!outname || first_in < 0) return 1;
    samFile *out = NULL;
    bam_hdr_t *ohdr = NULL;
    bam1_t *b = bam_init1();
    for (int i = first_in; i < argc; i++) {
        samFile *fp = sam_open(argv[i], "r");
        if (!fp) { fprintf(stderr, "shim: cannot open %s\n", argv[i]); return 1; }
        bam_hdr_t *hdr = sam_hdr_read(fp);
        if (!out) {
            out = sam_open(outname, "wb");
            ohdr = bam_hdr_dup(hdr);
            sam_hdr_write(out, ohdr);
        }
        while (sam_read1(fp, hdr, b) >= 0) sam_write1(out, ohdr, b);
        bam_hdr_destroy(hdr);
        sam_close(fp);
    }
    bam_destroy1(b);
    if (out) { sam_close(out); bam_hdr_destroy(ohdr); }
    return 0;
}

static int cmd_index(int argc, char **argv)
{
    if (argc < 1) return 1;
    return sam_index_build(argv[0], 0) < 0 ? 1 : 0;
}

int main(int argc, char **argv)
{
    if (argc < 2) { fprintf(stderr, "usage: samtools <view|merge|index> ...\n"); return 1; }
    if (strcmp(argv[1], "view") == 0) return cmd_view(argc - 2, argv + 2);
    if (strcmp(argv[1], "merge") == 0) return cmd_merge(argc - 2, argv + 2);
    if (strcmp(argv[1], "index") == 0) return cmd_index(argc - 2, argv + 2);
    fprintf(stderr, "shim: unsupported command %s\n", argv[1]);
    return 1;
}
