bool BlockMgr::fractionIsMet(CHRPOS overlapBases, CHRPOS totalLength, float fraction)
{
	//no overlap can never satisfy a fraction, and a record with no
	//aligned bases can not be covered by anything.
	if (overlapBases <= 0 || totalLength <= 0) {
		return false;
	}
	return ((float)overlapBases / (float)totalLength) >= fraction;
}

CHRPOS BlockMgr::getCoveredLength(const vector<overlapIntervalType> &intervals)
{
	if (intervals.empty()) {
		return 0;
	}
	//several database records may cover the same bases of the query record.
	//Merge the intervals so that each covered base is only counted once.
	_coveredIntervals = intervals;
	sort(_coveredIntervals.begin(), _coveredIntervals.end());

	CHRPOS coveredLength = 0;
	CHRPOS currStart = _coveredIntervals[0].first;
	CHRPOS currEnd = _coveredIntervals[0].second;
	for (size_t i = 1; i < _coveredIntervals.size(); i++) {
		if (_coveredIntervals[i].first > currEnd) {
			coveredLength += currEnd - currStart;
			currStart = _coveredIntervals[i].first;
			currEnd = _coveredIntervals[i].second;
		} else if (_coveredIntervals[i].second > currEnd) {
			currEnd = _coveredIntervals[i].second;
		}
	}
	coveredLength += currEnd - currStart;
	return coveredLength;
}

int BlockMgr::findBlockedOverlaps(RecordKeyVector &keyList, RecordKeyVector &hitList,
	                              RecordKeyVector &resultList, RecordKeyVector *overlapList)
{
	bool deleteKeyBlocks = false;
	if (keyList.empty()) {
		//get all the blocks for the query record, put them in it's list.
		getBlocks(keyList, deleteKeyBlocks);
	}
	_overlapBases.clear();
	_hitRecords.clear();
	_hitBlockLengths.clear();
	_hitOverlapBases.clear();
	_hitOverlapOffsets.clear();
	_hitOverlapIntervals.clear();

	//The blocks of a record are the record itself. Any bases between them, such
	//as the intron skipped by a spliced alignment, lie inside the record's span
	//but are not part of the record, and so are not part of its length.
	CHRPOS keyBlocksSumLength = getTotalBlockLength(keyList);

	//Loop through every database record the query intersected with, and find where
	//the blocks of the two records truly overlap. A record whose span overlapped,
	//but none of whose blocks did, is not an overlap at all.
	RecordKeyVector::iterator_type hitListIter = hitList.begin();
	for (; hitListIter != hitList.end(); hitListIter = hitList.next())
	{
		RecordKeyVector hitBlocks(*hitListIter);
		bool deleteHitBlocks = false;
		getBlocks(hitBlocks, deleteHitBlocks); //get all blocks for the hit record.

		_hitRecords.push_back(*hitListIter);
		//total length of the blocks for the hitRecord.
		_hitBlockLengths.push_back(getTotalBlockLength(hitBlocks));
		_hitOverlapOffsets.push_back(_hitOverlapIntervals.size());

		CHRPOS totalHitOverlap = 0;

		//loop through every block of the database record.
		RecordKeyVector::iterator_type hitBlockIter = hitBlocks.begin();
		for (; hitBlockIter != hitBlocks.end(); hitBlockIter = hitBlocks.next())
		{
			//loop through every block of the query record.
			RecordKeyVector::iterator_type keyListIter = keyList.begin();
			for (; keyListIter != keyList.end(); keyListIter = keyList.next())
			{
				const Record *keyBlock = *keyListIter;
				const Record *hitBlock = *hitBlockIter;

				CHRPOS maxStart = max(keyBlock->getStartPos(), hitBlock->getStartPos());
				CHRPOS minEnd = min(keyBlock->getEndPos(), hitBlock->getEndPos());
				CHRPOS overlap  = minEnd - maxStart;
				if (overlap > 0) {
					_hitOverlapIntervals.push_back(overlapIntervalType(maxStart, minEnd));
					totalHitOverlap += overlap;
				}
			}
		}
		_hitOverlapBases.push_back(totalHitOverlap);

		if (deleteHitBlocks) {
			deleteBlocks(hitBlocks);
		}
	}
	_hitOverlapOffsets.push_back(_hitOverlapIntervals.size());

	//Whether enough of the query record is covered (the -f criterion) is a property
	//of the query record, not of any one database record: the blocks of a split
	//record may well be covered by several database records, such as the exons of
	//a transcript. So measure how much of the query's blocks the database covers,
	//counting each query base only once.
	bool keyFractionMet = fractionIsMet(getCoveredLength(_hitOverlapIntervals),
	                                    keyBlocksSumLength, _overlapFractionA);

	//The -F criterion describes a database record, so it is measured for each hit
	//against that hit's own blocks. Requesting reciprocal overlap (-r) asks for the
	//same fraction on both sides.
	float hitFraction = _hasReciprocal ? _overlapFractionA : _overlapFractionB;

	for (size_t i = 0; i < _hitRecords.size(); i++)
	{
		if (_hitOverlapBases[i] == 0) {
			continue; //only the spans overlapped, not the blocks.
		}
		bool hitFractionMet = fractionIsMet(_hitOverlapBases[i], _hitBlockLengths[i], hitFraction);
		bool fractionsMet = _eitherFraction ? (keyFractionMet || hitFractionMet)
		                                    : (keyFractionMet && hitFractionMet);
		if (!fractionsMet) {
			continue;
		}
		_overlapBases.push_back((int)_hitOverlapBases[i]);
		resultList.push_back(_hitRecords[i]);
		if (overlapList != NULL) {
			for (size_t j = _hitOverlapOffsets[i]; j < _hitOverlapOffsets[i+1]; j++) {
				overlapList->push_back(allocateAndAssignRecord(keyList.getKey(),
				                                              _hitOverlapIntervals[j].first,
				                                              _hitOverlapIntervals[j].second));
			}
		}
	}
	if (deleteKeyBlocks) {
		deleteBlocks(keyList);
	}
	resultList.setKey(keyList.getKey());
	return (int)resultList.size();
}

if (getObeySplits()) {
	//With -split, a record exists only at its blocks, so all of the overlap
	//fraction criteria are measured against the block lengths rather than
	//the outer spans. See BlockMgr::findBlockedOverlaps.
	_splitBlockInfo = new BlockMgr(_overlapFractionA, _reciprocalFraction);
	_splitBlockInfo->setOverlapFractionB(_overlapFractionB);
	_splitBlockInfo->setEitherFraction(_eitherFraction);
}

